<template>
  <div class="coupon-wrapper">
    <ul class="list">
      <li class="no-select" @click="selectCoupon(0)">
        <span>不使用优惠券</span>
        <i class="icon iconfont" v-if="couponId == 0">&#xe611;</i>
      </li>
      <li class="item" v-for="(item, index) in list" :key="index" @click="selectCoupon(item.had_id)">
        <div class="left">
          <div v-if="item.is_discount == 0">
            <span>¥</span>
            <span class="num">{{item.discount}}</span>
          </div>
          <div v-if="item.is_discount == 1">
            <span class="num">{{item.discount_value}}</span>
            <span>折</span>
          </div>
        </div>
        <div class="right">
          <div>
            <div>满{{item.order_money}}元可用</div>
            <div>{{item.time}}</div>
          </div>
          <div v-if="item.had_id == couponId">
            <i class="icon iconfont">&#xe611;</i>
          </div>
        </div>
      </li>
    </ul>
  </div>
</template>

<script>
export default {
  name: 'Coupon',
  data () {
    return {
      list: [],
      couponId: ''
    }
  },
  created () {
    this.couponId = this.$route.query.couponId
    this.orderId = this.$route.query.orderId
    this.getCoupon()
  },
  methods: {
    selectCoupon (id) {
      this.$global.couponId = id
      this.$router.go(-1)
    },

    async getCoupon () {
      let res = await this.$api.getCoupon({ type: 'village_group', coupon_type: 'system', sysc_id: this.couponId, order_id: this.orderId })
      if (!res) return
      this.list = res
    }
  }
}
</script>

<style lang="stylus" scoped>
.coupon-wrapper
  background #efefef
  .list
    height 100%
    overflow-y auto
    .no-select
      background #fff
      margin 15px 15px 0
      padding 15px
      border-radius 4px
      flexbox()
      justify-content space-between
      align-items center
      .icon
        font-size 24px
        color #f5391c
    .item
      flexbox()
      margin 15px
      .left
        flex-grow 2
        background #f5391c
        color #fff
        border-right 2px dashed #fff
        border-radius 6px 0 0 6px
        flexbox()
        align-items center
        justify-content center
        font-size 14px
        font-weight bold
        position relative
        &::before, &::after
          content ''
          width 14px
          height 14px
          background #efefef
          border-radius 50%
          position absolute
          right -8px
          top -7px
        &::after
          top auto
          bottom -7px
        .num
          font-size 32px
          vertical-align text-bottom
          padding-left 5px
      .right
        background #fff
        flex-grow 4
        padding 20px 15px
        line-height 2
        border-radius 0 6px 6px 0
        flexbox()
        align-items center
        justify-content space-between
        .icon
          font-size 24px
          color #f5391c
</style>
